import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, plot, table, flow, build, chapterTests } from './lib.mjs';
import { r, range, F, Cm, bn, fr, mon, expand, pTex, binTerm, termsOf, pcoef, padd, ppow, asPoly, pterms, fStr, fTex, pascalRow, modpow, dec, decExact, decFr, fmul, fadd, fpow, feq, pascalFig, sd, spow, sadd } from './bt.mjs';

setUnit('cbse-11-mathematics-ch07');
await import('./questions.mjs');
await import('./questions2.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const must = (cond, msg) => { if (!cond) throw new Error(`self-check failed: ${msg}`); };
const T = (s) => `$${s}$`;
const N = (b) => Number(b);
const one = (m, names) => pTex(asPoly(m), names);
const ab = ['a', 'b'];
const A = (c, i, j) => mon(c, i, j);
const sumList = (xs) => xs.reduce((u, v) => u + v, 0n);
const subsets = (n, k) => { const out = []; for (let mask = 0; mask < 1 << n; mask++) { const ix = range(0, n - 1).filter((i) => mask & (1 << i)).map((i) => i + 1); if (ix.length === k) out.push(ix); } return out; };

// ================================================================ deck 1 visuals: Pascal's triangle and the theorem
// powers of (a + b) by repeated multiplication
const expRows = range(0, 5).map((n) => {
  const p = ppow(padd(asPoly(A(1, 1, 0)), asPoly(A(1, 0, 1))), n);
  must(pterms(p).map((m) => m.c.n).join() === pascalRow(n).join() && pterms(p).map((m) => m.c.n).join() === range(0, n).map((k) => Cm(n, k)).join(), `row ${n} coefficients`);
  return [T(n), T(pTex(p, ab))];
});
const tblExp = table(['Power $n$', 'Expansion of $(a + b)^{n}$ by multiplying the brackets out'], expRows, 'Table of the expansions of a plus b to the powers zero to five, each found by multiplying brackets: the coefficients are 1; 1, 1; 1, 2, 1; 1, 3, 3, 1; 1, 4, 6, 4, 1; and 1, 5, 10, 10, 5, 1.', 'The coefficients form a pattern.');
// choosing b from r of the four brackets
const chooseRows = range(0, 4).map((k) => {
  const subs = subsets(4, k);
  must(subs.length === N(Cm(4, k)) && subs.length === N(pascalRow(4)[k]) && pcoef(expand(A(1, 1, 0), A(1, 0, 1), 4), [4 - k, k]).n === BigInt(subs.length), `ways to pick b from ${k} of 4 brackets`);
  return [T(k), subs.length === 0 || k === 0 ? 'none' : subs.map((s) => `{${s.join(',')}}`).join(' '), T(subs.length), T(`a^{${4 - k}}b^{${k}}`)];
});
const tblChoose = table(['Brackets that give $b$ ($r$)', 'Which brackets, numbered $1$ to $4$', 'Ways', 'Term formed'], chooseRows, 'Table for the fourth power of a plus b: choosing b from none, one, two, three or all four of the numbered brackets can be done in 1, 4, 6, 4 and 1 ways, giving the terms a to the fourth, a cubed b, a squared b squared, a b cubed and b to the fourth.', 'The coefficient counts the ways of picking the brackets.');
const figPascal = pascalFig(8, [7, 3], 'Pascal triangle drawn with rows zero to seven: each row starts and ends with 1 and every inner number is the sum of the two above it; the dashed lines show 15 plus 20 giving 35 in the row for the seventh power.', r`Each inner number is the sum of the two above: $15 + 20 = 35$.`);
must(pascalRow(6)[2] + pascalRow(6)[3] === pascalRow(7)[3] && pascalRow(7)[3] === 35n && pascalRow(7).join() === '1,7,21,35,35,21,7,1', '15 + 20 = 35');
const tblHist = table(['Place and time (about)', 'Who', 'What they did'], [
  ['India, about the second century before the common era', 'Pingala', 'Counted patterns of short and long syllables in poetry with these numbers; later writers such as Halayudha (tenth century) set them out as the "staircase of Mount Meru"'],
  ['Persia, about the eleventh and twelfth centuries', 'Al-Karaji and Omar Khayyam', 'Used the number pattern to expand powers of a sum and to take roots'],
  ['China, about the thirteenth century', 'Yang Hui', 'Published the triangle, still called Yang Hui\'s triangle in China'],
  ['France, about the 1650s', 'Blaise Pascal', 'Studied the triangle closely and used it in counting and chance, so Europe names it after him'],
  ['England, about the 1660s', 'Isaac Newton', 'Extended the expansion beyond whole-number powers (not needed in this chapter)'],
], 'Timeline table of the triangle of binomial coefficients: Pingala in India, Al-Karaji and Omar Khayyam in Persia, Yang Hui in China, Blaise Pascal in France and Isaac Newton in England, with what each contributed.', 'The same triangle was found in many places.');
const thm6 = expand(A(1, 1, 0), A(1, 0, 1), 6);
const tblThm = table(['$r$', r`$\binom{6}{r}$`, r`Term $\binom{6}{r}x^{6-r}y^{r}$`], range(0, 6).map((k) => [T(k), T(`${Cm(6, k)}`), T(one(binTerm(A(1, 1, 0), A(1, 0, 1), 6, k), ['x', 'y']))]), 'Table of the seven terms of x plus y to the sixth power from the binomial theorem: the coefficients 1, 6, 15, 20, 15, 6, 1 multiply x to the sixth, x to the fifth y, and so on down to y to the sixth.', r`$(x+y)^{6} = ${pTex(thm6, ['x', 'y'])}$.`);
must(range(0, 6).every((k) => pcoef(thm6, [6 - k, k]).n === Cm(6, k)), 'theorem for n = 6');
const featRows = range(0, 8).map((n) => { const row = pascalRow(n); const alt = row.reduce((u, v, i) => (i % 2 ? u - v : u + v), 0n); must(sumList(row) === 2n ** BigInt(n) && alt === (n === 0 ? 1n : 0n) && row.length === n + 1, `row ${n} sums`); return [T(n), row.join(', '), T(`2^{${n}} = ${2n ** BigInt(n)}`), T(alt)]; });
const tblFeat = table(['$n$', 'Coefficients', 'Sum of the row', 'Alternating sum'], featRows, 'Table of rows zero to eight of Pascal triangle with the sum of each row, which is two to the power n, and the alternating sum, which is zero for every n from one onward.', r`Put $a = b = 1$: sum $2^{n}$. Put $a = 1$, $b = -1$: sum $0$.`);
// worked example 1: (3x - 2y)^4
const we1 = expand(A(3, 1, 0), A(-2, 0, 1), 4);
must(pTex(we1, ['x', 'y']) === '81x^{4} - 216x^{3}y + 216x^{2}y^{2} - 96xy^{3} + 16y^{4}', '(3x - 2y)^4');
const tblWE1 = table(['$r$', r`Term $\binom{4}{r}(3x)^{4-r}(-2y)^{r}$`, 'Simplified'], [...termsOf(A(3, 1, 0), A(-2, 0, 1), 4).map((m, k) => [T(k), T(`${bn(4, k)}(3x)^{${4 - k}}(-2y)^{${k}}`), T(one(m, ['x', 'y']))]), ['Sum', '', T(pTex(we1, ['x', 'y']))]], 'Table expanding three x minus two y to the fourth power: the five terms are 81 x to the fourth, minus 216 x cubed y, plus 216 x squared y squared, minus 96 x y cubed and plus 16 y to the fourth.', 'Signs alternate because the second term is negative.');
// negative powers: (x - 1/x)^4
const fr4 = expand(A(1, 1, 0), A(-1, -1, 0), 4);
must(pTex(fr4, ['x', 'y']) === 'x^{4} - 4x^{2} + 6 - 4x^{-2} + x^{-4}', '(x - 1/x)^4');
const tblFrac = table(['$r$', r`Term $\binom{4}{r}x^{4-r}\left(-\dfrac{1}{x}\right)^{r}$`, 'Simplified'], [...termsOf(mon(1, 1), mon(-1, -1), 4).map((m, k) => [T(k), T(`${bn(4, k)}x^{${4 - k}}\\left(-\\dfrac{1}{x}\\right)^{${k}}`), T(one(m, ['x']))]), ['Sum', '', T(pTex(expand(mon(1, 1), mon(-1, -1), 4), ['x']))]], 'Table expanding x minus one over x to the fourth power: the terms are x to the fourth, minus 4 x squared, 6, minus 4 over x squared and one over x to the fourth.', r`A negative second term gives alternating signs; $\left(\dfrac{1}{x}\right)^{r} = x^{-r}$.`);
// worked example 2: 52^4 = (50 + 2)^4
const we2parts = range(0, 4).map((k) => Cm(4, k) * 50n ** BigInt(4 - k) * 2n ** BigInt(k));
must(sumList(we2parts) === 52n ** 4n && 52n ** 4n === 7311616n && we2parts.join() === '6250000,1000000,60000,1600,16', '52^4');
const tblWE2 = table(['$r$', 'Term', 'Value'], [...we2parts.map((v, k) => [T(k), T(`${bn(4, k)} \\times 50^{${4 - k}} \\times 2^{${k}}`), T(v)]), ['Total', T('52^{4}'), T(sumList(we2parts))]], 'Table computing 52 to the fourth power as fifty plus two to the fourth: the five terms are 6250000, 1000000, 60000, 1600 and 16, and they add up to 7311616.', 'Split the number as a round number plus a small one.');
// approximation of 1.03^6
const x03 = decFr('0.03');
const apTerms = range(0, 6).map((k) => fmul(fr(Cm(6, k)), fpow(x03, k)));
const apSums = apTerms.map((_, k) => apTerms.slice(0, k + 1).reduce(fadd));
must(dec(apSums[2], 4) === '1.1935' && dec(apSums[6], 6) === '1.194052' && feq(apSums[6], fpow(decFr('1.03'), 6)) && decExact(apSums[3]) === '1.19404', '1.03^6');
const tblApprox = table(['$r$', r`Term $\binom{6}{r}(0.03)^{r}$`, 'Running sum'], apTerms.map((t, k) => [T(k), T(decExact(t)), T(decExact(apSums[k]))]), 'Table of the terms of one plus 0.03 to the sixth power: the terms get smaller quickly, so after three terms the running sum is 1.1935 and the exact value 1.194052296 is reached after all seven terms.', 'Later terms are tiny: a few terms give a good estimate.');
// remainders
const remRows = [[13n, 30n, 12n, 1n, '(12 + 1)'], [8n, 20n, 7n, 1n, '(7 + 1)'], [11n, 25n, 12n, -1n, '(12 - 1)']].map(([b, e, m, s, w]) => { const rem = modpow(b, e, m); must(rem === modpow(b, e, m) && (b ** e) % m === rem, `${b}^${e} mod ${m}`); return [T(`${b}^{${e}} \\div ${m}`), T(`${w}^{${e}}`), s === 1n ? T(`\\text{the last term is } 1`) : T(`\\text{the last term is } (-1)^{${e}} = -1`), T(rem)]; });
const rem50 = modpow(7, 42, 50);
must(rem50 === 49n && (7n ** 42n) % 50n === 49n && 49n ** 21n % 50n === 49n, '7^42 mod 50');
remRows.push([T('7^{42} \\div 50'), T('(50 - 1)^{21}'), T('\\text{the last term is } (-1)^{21} = -1'), T(rem50)]);
const tblRem = table(['Number', 'Written as', 'The term without the multiple', 'Remainder'], remRows, 'Table of remainders found with the binomial theorem: 13 to the thirtieth over 6 leaves 1, 8 to the twentieth over 7 leaves 1, 11 to the twenty-fifth over 12 leaves 11, and 7 to the forty-second over 50 leaves 49.', 'Write the number as a multiple plus or minus 1.');
const tblWE3 = table(['Step', 'Working'], [['Make a power of $49$', r`$7^{42} = (7^{2})^{21} = 49^{21}$`], ['Write $49$ next to a multiple of $50$', r`$49^{21} = (50 - 1)^{21}$`], ['Expand', r`${'$'}${bn(21, 0)}50^{21} - ${bn(21, 1)}50^{20} + \cdots - 1$`], ['Every term but the last has the factor $50$', r`$7^{42} = 50k - 1$`], ['Remainder', r`$50k - 1 = 50(k - 1) + 49$, so the remainder is $${rem50}$`]], 'Table finding the remainder of 7 to the forty-second power on division by 50: write it as 49 to the twenty-first, then as fifty minus one to the twenty-first; every term except the last has a factor 50, so it equals 50k minus 1, and the remainder is 49.', r`$7^{42}$ leaves remainder $49$ on division by $50$.`);
const summary1 = flow('LR', [['c', r`Choose $b$ from $r$ brackets: coefficient $\binom{n}{r}$`], ['p', r`Pascal's triangle gives row $n$`], ['t', r`$(a+b)^{n} = \sum \binom{n}{r}a^{n-r}b^{r}$`], ['u', 'Values, approximations, remainders']], [['c', 'p'], ['p', 't'], ['t', 'u']], 'Summary flow: choosing b from r of the n brackets gives the coefficient n choose r; Pascal triangle lists these coefficients; the binomial theorem adds up all the terms; and it is then used for values, approximations and remainders.', 'From brackets to the theorem and its uses.');

// ================================================================ deck 2 visuals: general term, middle term
const ex6 = expand(A(1, 1, 0), A(2, 0, 0), 6);
const tblT6 = table(['Term', '$r$', r`$\binom{6}{r}x^{6-r}\,2^{r}$`, 'Simplified'], termsOf(mon(1, 1), mon(2, 0), 6).map((m, k) => [T(`T_{${k + 1}}`), T(k), T(`${bn(6, k)}x^{${6 - k}}2^{${k}}`), T(one(m, ['x']))]), 'Table of the seven terms of x plus 2 to the sixth power, numbered T1 to T7: x to the sixth, 12 x to the fifth, 60 x to the fourth, 160 x cubed, 240 x squared, 192 x and 64.', 'Seven terms for the sixth power.');
must(pTex(ex6, ['x']) === 'x^{6} + 12x^{5} + 60x^{4} + 160x^{3} + 240x^{2} + 192x + 64', '(x+2)^6');
const g7 = termsOf(A(1, 1, 0), A(1, 0, 1), 7);
const tblGen = table(['Term number', '$r$', r`$T_{r+1} = \binom{7}{r}a^{7-r}b^{r}$`, 'Coefficient'], g7.map((m, k) => [T(`T_{${k + 1}}`), T(k), T(`${bn(7, k)}a^{${7 - k}}b^{${k}}`), T(m.c.n)]), 'Table of the eight terms of a plus b to the seventh power: the term number is r plus one, and the coefficients are 1, 7, 21, 35, 35, 21, 7 and 1.', r`The $(r+1)$th term has $b^{r}$ and the coefficient $\binom{n}{r}$.`);
const we1b = binTerm(mon(3, 1), mon(fr(-1, 2), -1), 8, 3);
must(we1b.c.n === -1701n && we1b.c.d === 1n && we1b.e[0] === 2 && Cm(8, 3) * 243n === 13608n && 13608 / 8 === 1701, 'T4 = -1701 x^2');
const tblWE1b = table(['Step', 'Working'], [['General term', r`$T_{r+1} = \binom{8}{r}(3x)^{8-r}\left(-\dfrac{1}{2x}\right)^{r}$`], ['Fourth term', r`$r + 1 = 4$, so $r = 3$`], ['Substitute', r`$\binom{8}{3}(3x)^{5}\left(-\dfrac{1}{2x}\right)^{3}$`], ['Simplify', r`$56 \times 243x^{5} \times \left(-\dfrac{1}{8x^{3}}\right)$`], ['Value', r`$T_{4} = -1701x^{2}$`]], 'Table finding the fourth term of three x minus one over two x to the eighth: r is three, the term is 8 choose 3 times three x to the fifth times minus one over two x cubed, and it simplifies to minus 1701 x squared.', 'The fourth term has $r = 3$.');
const x10 = termsOf(mon(1, 3), mon(2, -2), 10);
must(x10.every((m, k) => m.e[0] === 30 - 5 * k) && x10.filter((m) => m.e[0] === 0).length === 1 && x10[6].c.n === 13440n && Cm(10, 6) * 64n === 13440n, 'x^3 + 2/x^2 to the tenth');
const tblExp10 = table(['$r$', 'Power of $x$ in $T_{r+1}$', r`Coefficient $\binom{10}{r}2^{r}$`], x10.map((m, k) => [T(k), T(30 - 5 * k), T(m.c.n) + (m.e[0] === 0 ? ' (independent of $x$)' : '')]), 'Table for x cubed plus 2 over x squared to the tenth power: the power of x in the term with index r is 30 minus 5r, which is zero when r is 6, where the coefficient is 210 times 64, which is 13440.', r`The power is $30 - 5r$; it is $0$ at $r = 6$.`);
const tblWE2b = table(['Step', 'Working'], [['General term', r`$T_{r+1} = \binom{10}{r}(x^{3})^{10-r}\left(\dfrac{2}{x^{2}}\right)^{r} = \binom{10}{r}2^{r}x^{30-5r}$`], ['Independent of $x$', r`$30 - 5r = 0$, so $r = 6$`], ['Value', r`$\binom{10}{6}2^{6} = 210 \times 64 = ${x10[6].c.n}$`]], 'Table finding the term independent of x in x cubed plus 2 over x squared to the tenth: the power of x is 30 minus 5r, which is zero at r equal to 6, and the term is 210 times 64, which is 13440.', 'Solve for $r$, then substitute.');
const row10 = pascalRow(10);
must(Math.max(...row10.map(N)) === 252 && row10.indexOf(252n) === 5 && row10.join() === range(0, 10).map((k) => Cm(10, k)).join(), 'row 10 peaks at 252');
const plotMid = plot({ x: [0, 10], y: [0, 270], xl: 'r (lower number)', yl: 'binomial coefficient', pts: row10.map((v, k) => [k, N(v), String(v), 'free']), series: [{ label: 'the binomial coefficients of the tenth power joined by a line', points: row10.map((v, k) => [k, N(v)]), kind: 'line' }] }, 'Plot of the binomial coefficients of the tenth power for r from 0 to 10: 1, 10, 45, 120, 210, 252, 210, 120, 45, 10, 1. The picture is symmetric and highest at r equal to 5, the middle term.', r`The middle term of $(a+b)^{10}$ has $r = 5$: $\binom{10}{5} = 252$.`);
const we3 = termsOf(A(1, 1, 0), A(2, 0, 1), 7);
must(we3[3].c.n === 280n && we3[3].e.join() === '4,3' && we3[4].c.n === 560n && we3[4].e.join() === '3,4' && we3.length === 8, '(x + 2y)^7 middle terms');
const tblWE3b = table(['Term', 'Working', 'Value'], [[r`$T_{4}$`, r`$\binom{7}{3}x^{4}(2y)^{3} = 35 \times 8\,x^{4}y^{3}$`, T(one(we3[3], ['x', 'y']))], [r`$T_{5}$`, r`$\binom{7}{4}x^{3}(2y)^{4} = 35 \times 16\,x^{3}y^{4}$`, T(one(we3[4], ['x', 'y']))]], 'Table of the two middle terms of x plus 2y to the seventh power: the fourth term is 35 times 8 x to the fourth y cubed, which is 280 x to the fourth y cubed, and the fifth term is 35 times 16 x cubed y to the fourth, which is 560 x cubed y to the fourth.', 'Odd power: the two middle terms are $T_{4}$ and $T_{5}$.');
const flowFind = flow('LR', [['g', r`Write the general term $T_{r+1}$`], ['e', r`Collect the power of $x$ in terms of $r$`], ['s', r`Solve: power of $x$ $= k$`], ['d', r`Is $r$ a whole number from $0$ to $n$?`], ['y', 'Yes: substitute $r$ and simplify'], ['n', 'No: there is no such term']], [['g', 'e'], ['e', 's'], ['s', 'd'], ['d', 'y', 'yes'], ['d', 'n', 'no']], 'Flow chart for finding the term that contains x to the power k: write the general term, collect the power of x in terms of r, solve for r, and if r is a whole number from zero to n substitute it, otherwise there is no such term.', r`Always check that $r$ is a whole number between $0$ and $n$.`);
const eqHits = range(8, 60).filter((n) => Cm(n, 7) === Cm(n, 13));
must(eqHits.join() === '20' && Cm(20, 7) === 77520n && Cm(20, 13) === 77520n, 'n = 20');
const tblWE4 = table(['Step', 'Working'], [['The coefficients of $x^{7}$ and $x^{13}$', r`$\binom{n}{7}$ and $\binom{n}{13}$`], ['Equal binomial coefficients with different lower numbers', r`$7 + 13 = n$`], ['Value', r`$n = 20$`], ['Check', `${T(`${bn(20, 7)} = ${bn(20, 13)} = ${Cm(20, 7)}`)}`]], 'Table solving for n when the coefficients of x to the seventh and x to the thirteenth in one plus x to the n are equal: the lower numbers 7 and 13 add up to n, so n is 20, and both coefficients equal 77520.', r`$\binom{n}{r} = \binom{n}{s}$ with $r \ne s$ means $r + s = n$.`);
const symPairs = [[2, 10], [3, 9], [4, 8], [5, 7]].map(([u, v]) => { must(Cm(12, u) === Cm(12, v) && u + v === 12 && pascalRow(12)[u] === pascalRow(12)[v], `12C${u} = 12C${v}`); return [T(`${u} + ${v} = 12`), T(`${bn(12, u)} = ${bn(12, v)}`), T(Cm(12, u))]; });
const tblSym = table(['Lower numbers adding to $12$', 'Equal binomial coefficients', 'Value'], symPairs, 'Table of equal binomial coefficients for the twelfth power: 12 choose 2 equals 12 choose 10 which is 66, 12 choose 3 equals 12 choose 9 which is 220, 12 choose 4 equals 12 choose 8 which is 495, and 12 choose 5 equals 12 choose 7 which is 792.', r`If the lower numbers $r \ne s$ give equal coefficients, then $r + s = n$.`);
const summary2 = flow('LR', [['g', r`$T_{r+1} = \binom{n}{r}a^{n-r}b^{r}$`], ['k', 'Particular term: solve for $r$'], ['m', r`Middle: even $n$ one term, odd $n$ two`], ['e', r`Equal coefficients: $r + s = n$`]], [['g', 'k'], ['g', 'm'], ['m', 'e']], 'Summary flow: the general term leads to particular terms by solving for r; to the middle terms, one for an even power and two for an odd power; and to equal coefficients, whose lower numbers add up to n.', 'General, particular and middle terms.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Binomial Theorem — Part 1: Pascal\'s triangle and the expansion of $(a+b)^{n}$',
  goals: ['Read the coefficients of a power of a sum from Pascal\'s triangle', 'State and prove the binomial theorem for a positive whole-number power', 'Expand sums, differences and expressions with fractions', 'Use the theorem to evaluate and approximate powers of numbers', 'Find remainders with the theorem'],
  slides: [
    sl('title', 'Binomial theorem, Part 1: Expanding a power of a sum', { b: 'How can the fifth power of a sum be written out without multiplying five brackets one after another?', v: tblExp, n: 'Welcome. The table shows the powers of a plus b, from the zeroth to the fifth, found by multiplying brackets out one at a time. Look at the numbers in front of the terms: one, one; then one, two, one; then one, three, three, one. In this chapter you will find a rule that writes any such expansion at once, using Pascal\'s triangle and the binomial theorem.' }),
    sl('concept', 'What you will be able to do', { ul: ['Read coefficients from **Pascal\'s triangle**', 'State and prove the **binomial theorem**', 'Expand sums, differences and expressions with **fractions**', 'Evaluate and approximate numbers such as $99^{3}$ and $1.03^{6}$', 'Find **remainders** with the theorem'], n: 'Here are your goals. You will read coefficients from Pascal\'s triangle, and state and prove the binomial theorem. You will expand sums and differences, including expressions with fractions. You will use the theorem to find values of powers of numbers, to estimate powers close to one, and to find remainders. These ideas appear in objective items, short answers and long answers.' }),
    sl('concept', 'Where the coefficients come from', { b: r`In $(a+b)^{4}$ every term is made by taking $a$ or $b$ from each of the four brackets. A term with $b$ from exactly $r$ brackets is $a^{4-r}b^{r}$, and **the number of ways to pick those $r$ brackets is its coefficient**.`, v: tblChoose, m: [r`\binom{n}{r} = \dfrac{n!}{r!\,(n-r)!}`], n: 'Think of the fourth power as four brackets multiplied together. From each bracket we take either the first letter or the second. If the second letter is taken from exactly two brackets, there are six ways to choose which two, so that term has coefficient six. The table lists all the choices. The coefficient is the number of ways to choose the brackets, written n choose r.' }),
    sl('concept', 'Pascal\'s triangle', { b: r`Write $1$ at the top. Every row begins and ends with $1$, and each inner entry is **the sum of the two entries above it**. Row $n$ (the top row is row $0$) lists the coefficients of $(a+b)^{n}$.`, v: figPascal, m: [r`\binom{n}{r} + \binom{n}{r-1} = \binom{n+1}{r}`], n: 'This is Pascal\'s triangle. The top row is row zero. Each row begins and ends with one, and every number inside is the sum of the two numbers above it. The dashed lines show fifteen plus twenty making thirty-five. Row seven reads one, seven, twenty-one, thirty-five, thirty-five, twenty-one, seven, one, and these are the coefficients of the seventh power of a plus b.' }),
    sl('concept', 'A triangle with a long history', { b: 'The triangle of binomial coefficients was found again and again, long before it was named after Pascal.', v: tblHist, n: 'This triangle has a long history. In India, Pingala used it in the study of poetic metres more than two thousand years ago, and later writers called it the staircase of Mount Meru. Persian mathematicians used it to expand powers, Yang Hui published it in China, and Blaise Pascal studied it closely in France in the sixteen fifties. Newton later extended the expansion beyond whole number powers.' }),
    sl('concept', 'The binomial theorem', { b: r`For every positive integer $n$: $(a + b)^{n} = \displaystyle\sum_{r=0}^{n} \binom{n}{r}\,a^{n-r}b^{r}$. There are $n+1$ terms; the power of $a$ falls from $n$ to $0$ and the power of $b$ rises from $0$ to $n$.`, v: tblThm, m: [r`(a+b)^{n} = \binom{n}{0}a^{n} + \binom{n}{1}a^{n-1}b + \cdots + \binom{n}{n}b^{n}`], n: 'Here is the binomial theorem. The nth power of a plus b is the sum, over r from zero to n, of n choose r times a to the power n minus r times b to the power r. The table applies it to the sixth power: the coefficients one, six, fifteen, twenty, fifteen, six, one, with x falling and y rising. The proof is the counting argument you have just seen, which you will write out in the exercises.' }),
    sl('concept', 'Features of the expansion', { ul: [r`There are **$n + 1$ terms**; in every term the powers add up to $n$`, r`Terms equally far from the two ends have **equal coefficients**: $\binom{n}{r} = \binom{n}{n-r}$`, r`The coefficients add up to $2^{n}$ (put $a = b = 1$)`, r`In $(a - b)^{n}$ the signs **alternate**; the alternating sum is $0$`], v: tblFeat, n: 'Look at the rows. There are n plus one terms and the powers in each term add up to n. The coefficients are symmetric: the same numbers appear from both ends. Putting a and b both equal to one shows that the coefficients of a row add up to two to the power n. Putting a equal to one and b equal to minus one makes the alternating sum zero for every n from one onward.' }),
    sl('check', 'Quick check: how many terms?', { b: 'How many terms does the expansion of a sum raised to a given power have?', chk: 'm01', n: 'Count the values that the power of the second letter takes.' }),
    sl('example', 'Worked example 1: a difference', { b: r`Expand $(3x - 2y)^{4}$.`, ul: [r`**Row for $n = 4$ —** $1, 4, 6, 4, 1$`, r`**First term $3x$, second term $-2y$**`, r`**Result —** $81x^{4} - 216x^{3}y + 216x^{2}y^{2} - 96xy^{3} + 16y^{4}$`], v: tblWE1, n: 'Take three x as the first term and minus two y as the second. The row for the fourth power is one, four, six, four, one. The first term is three x to the fourth, which is eighty-one x to the fourth. The second is four times twenty-seven x cubed times minus two y, which is minus two hundred sixteen x cubed y. Continue in the same way. The signs alternate because the second term is negative.' }),
    sl('check', 'Quick check: symmetry of the coefficients', { b: 'Are all thirteen coefficients in the expansion of a sum to the twelfth power different from one another?', chk: 'tf1', n: 'Recall that terms equally far from the two ends have equal coefficients.' }),
    sl('concept', 'Fractions and negative powers', { b: r`When a term has a fraction, write $\dfrac{1}{x}$ as $x^{-1}$ and combine the powers of $x$. For $\left(x - \dfrac{1}{x}\right)^{4}$ the powers of $x$ go $4, 2, 0, -2, -4$.`, v: tblFrac, n: 'When one of the terms is a fraction, write one over x as x to the power minus one, and combine the powers. In the expansion of x minus one over x, to the fourth, the powers of x go four, two, zero, minus two, minus four. The middle term is the constant six. The signs alternate because the second term is negative, and the coefficients are still one, four, six, four, one.' }),
    sl('example', 'Worked example 2: a number as a sum', { b: r`Find the value of $52^{4}$ by writing $52 = 50 + 2$.`, ul: [r`**Expand —** $(50 + 2)^{4}$ with the row $1, 4, 6, 4, 1$`, r`**Terms —** $6250000,\ 1000000,\ 60000,\ 1600,\ 16$`, r`**Total —** $7311616$`], v: tblWE2, n: 'To find fifty-two to the fourth, write fifty-two as fifty plus two. The terms are fifty to the fourth, which is six million two hundred fifty thousand, then four times fifty cubed times two, which is one million, then six times fifty squared times four, which is sixty thousand, then sixteen hundred, then sixteen. Their sum is seven million three hundred eleven thousand six hundred sixteen.' }),
    sl('check', 'Quick check: one expansion, two substitutions', { b: 'What is the sum of the entries of the row of Pascal\'s triangle that begins one, six?', chk: 'fb2', n: 'Put both letters equal to one.' }),
    sl('concept', 'Powers close to one', { b: r`For a small number $x$, $(1 + x)^{n} = 1 + nx + \dbinom{n}{2}x^{2} + \cdots$ and each later term is much smaller than the one before. A few terms give a good estimate.`, v: tblApprox, n: 'When x is small, the terms of one plus x to the power n shrink very fast. For one point zero three to the sixth, the terms are one, then zero point one eight, then zero point zero one three five, and so on. After three terms the running sum is one point one nine three five, and the next term only changes the third decimal place. All seven terms give the exact value, one point one nine four zero five two.' }),
    sl('check', 'Quick check: a three-term estimate', { b: 'Using only the first three terms of the expansion of one plus a small number, estimate the eighth power of one point zero one.', chk: 'm08', n: 'Use one plus n x plus n choose two times x squared.' }),
    sl('concept', 'Remainders with the theorem', { b: r`To find the remainder of $b^{e}$ on division by $m$, write $b$ as a multiple of $m$ plus or minus a small number. In $(km \pm 1)^{e}$ every term but the last contains $m$.`, v: tblRem, n: 'To find a remainder, write the base as a multiple of the divisor, plus or minus a small number. In the expansion every term except the last has the divisor as a factor. So the remainder depends only on the last term. If the small number is plus one, the remainder is one. If it is minus one and the power is odd, the number is a multiple minus one, so the remainder is the divisor minus one.' }),
    sl('example', 'Worked example 3: a remainder', { b: r`Find the remainder when $7^{42}$ is divided by $50$.`, ul: [r`**Make 49 —** $7^{42} = 49^{21}$`, r`**Write —** $49^{21} = (50 - 1)^{21}$`, r`**Only the last term has no factor 50 —** $(-1)^{21} = -1$`, r`**Remainder —** $50k - 1 = 50(k-1) + 49$, so $49$`], v: tblWE3, n: 'First write seven to the forty-second as forty-nine to the twenty-first. Now forty-nine is fifty minus one, so we expand fifty minus one to the twenty-first. Every term except the last has the factor fifty. The last term is minus one to the odd power, which is minus one. So the number is fifty k minus one, and that equals fifty times k minus one, plus forty-nine. The remainder is forty-nine.' }),
    sl('summary', 'Summary', { ul: [r`$b$ taken from $r$ brackets gives the coefficient $\binom{n}{r}$`, 'Row $n$ of Pascal\'s triangle gives the coefficients', r`$(a+b)^{n} = \sum_{r=0}^{n}\binom{n}{r}a^{n-r}b^{r}$, $n + 1$ terms, sum of coefficients $2^{n}$`, 'Signs alternate when the second term is negative', 'Near-one powers and remainders: a few terms or a nearby multiple'], v: summary1, n: 'To sum up. A coefficient counts the ways of choosing which brackets give the second letter. Pascal\'s triangle lists these numbers row by row. The binomial theorem adds the terms, giving n plus one terms in all, and the coefficients of a row add up to two to the power n. A negative second term makes the signs alternate. The theorem also gives values of powers, good estimates for powers close to one, and remainders.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Expansion (2–5 marks):** the row or $\\binom{n}{r}$ for the coefficients, the substitution, the simplified terms', '**Numerical value (2–3 marks):** the split of the number, the terms, the total', '**Proof (3–5 marks):** one letter chosen from each bracket; $r$ brackets give $\\binom{n}{r}$; add over $r$', '**Mistake:** losing the sign of a negative second term', '**Mistake:** forgetting to raise the number in front of a letter to the power, as in $(3x)^{4}$', '**Mistake:** writing $(a+b)^{n} = a^{n} + b^{n}$'], n: 'In expansion questions, marks go for the coefficients, for substituting the two terms correctly and for simplifying each term. In number questions, show how you split the number and list the terms. For the proof, say one letter is chosen from each bracket, count the ways, and add. Avoid three slips: losing the sign of a negative term, forgetting to raise the number in front of a letter to the power, and writing the sum of two powers.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2,
  title: 'Binomial Theorem — Part 2: General term, middle terms and applications',
  goals: ['Write the general term of the expansion', 'Find a particular term and the term independent of $x$', 'Find the middle term or terms', 'Use equal binomial coefficients to find an unknown power'],
  slides: [
    sl('title', 'Binomial theorem, Part 2: Finding one term at a time', { b: r`The expansion of $(x + 2)^{6}$ has seven terms. How can we find just the fourth, without writing out the rest?`, v: tblT6, n: 'Welcome to part two. The table shows all seven terms of x plus two, to the sixth power, numbered from the first to the seventh. Writing them all out is slow for a large power, so we look for a formula for any one term, called the general term. Then we find the term free of x, the middle terms, and a quick rule for equal coefficients. This part is for formative assessment, so focus on understanding.' }),
    sl('concept', 'What you will be able to do', { ul: ['Write the **general term** $T_{r+1}$', 'Find a **particular term** and the term independent of $x$', 'Find the **middle term(s)**', 'Use **equal binomial coefficients** to find $n$'], n: 'Here are your goals. You will write the general term of an expansion and use it to find a particular term, including the term that does not contain x. You will find the middle terms, and you will use equal binomial coefficients to find an unknown power. This part is for formative assessment, so the aim is understanding rather than speed.' }),
    sl('concept', 'The general term', { b: r`In $(a + b)^{n}$ the **$(r+1)$th term** is $T_{r+1} = \dbinom{n}{r}a^{n-r}b^{r}$, for $r = 0, 1, \ldots, n$. The term number is always one more than $r$.`, v: tblGen, m: [r`T_{r+1} = \binom{n}{r}a^{n-r}b^{r}`], n: 'The general term is the formula for any one term. The term with the second letter raised to the power r is the term number r plus one. So the first term has r equal to zero, and the fourth term has r equal to three. The table lists the eight terms of the seventh power of a plus b. Be careful: the term number is one more than r.' }),
    sl('example', 'Worked example 1: a particular term', { b: r`Find the fourth term of $\left(3x - \dfrac{1}{2x}\right)^{8}$.`, ul: [r`**Fourth term —** $r = 3$`, r`**Substitute —** $\binom{8}{3}(3x)^{5}\left(-\dfrac{1}{2x}\right)^{3}$`, r`**Value —** $56 \times 243x^{5} \times \left(-\dfrac{1}{8x^{3}}\right) = -1701x^{2}$`], v: tblWE1b, n: 'The fourth term has r equal to three. Substitute into the general term: eight choose three, times three x to the fifth, times minus one over two x, cubed. Eight choose three is fifty-six, and three to the fifth is two hundred forty-three. The cube of minus one over two x is minus one over eight x cubed. Multiplying gives minus seventeen hundred one, times x squared.' }),
    sl('check', 'Quick check: a fourth term', { b: 'Which expression is the fourth term in the expansion of two a plus b, to the sixth power?', chk: 'm13', n: 'The fourth term has r equal to three.' }),
    sl('concept', 'Finding a particular power of x', { b: r`To find the term containing $x^{k}$, write the power of $x$ in $T_{r+1}$ in terms of $r$, set it equal to $k$ and solve. Take $k = 0$ for the term **independent of $x$**.`, v: flowFind, n: 'To find the term that contains a given power of x, write the general term and collect the power of x in terms of r. Set it equal to the power you want and solve for r. Then check that r is a whole number from zero up to n. If it is, substitute and simplify. If it is not, there is no such term. For the term free of x, ask for the power zero.' }),
    sl('concept', 'The power of x in each term', { b: r`In $\left(x^{3} + \dfrac{2}{x^{2}}\right)^{10}$ the power of $x$ in $T_{r+1}$ is $3(10 - r) - 2r = 30 - 5r$, so only multiples of $5$ occur.`, v: tblExp10, m: [r`T_{r+1} = \binom{10}{r}2^{r}x^{30-5r}`], n: 'Here is an example. In x cubed plus two over x squared, to the tenth, the power of x in the term with index r is thirty minus five r. The table lists it for every r from zero to ten. Only multiples of five appear. The power is zero when r is six, so that is the term free of x, with coefficient two hundred ten times sixty-four.' }),
    sl('example', 'Worked example 2: the term independent of x', { b: r`Find the term independent of $x$ in $\left(x^{3} + \dfrac{2}{x^{2}}\right)^{10}$.`, ul: [r`**General term —** $\binom{10}{r}2^{r}x^{30-5r}$`, r`**Set the power to 0 —** $30 - 5r = 0$, so $r = 6$`, r`**Value —** $\binom{10}{6}2^{6} = 210 \times 64 = 13440$`], v: tblWE2b, n: 'Write the general term: ten choose r, times two to the r, times x to the power thirty minus five r. For the term free of x, the power must be zero, so r is six. The term is ten choose six, times two to the sixth, which is two hundred ten times sixty-four. That is thirteen thousand four hundred forty. Notice that r is a whole number in range, so the term exists.' }),
    sl('concept', 'Middle terms', { b: r`If $n$ is **even**, there is **one** middle term, $T_{n/2+1}$. If $n$ is **odd**, there are **two**, $T_{(n+1)/2}$ and $T_{(n+3)/2}$. The binomial coefficients rise to the middle and fall again.`, v: plotMid, m: [r`n \text{ even: } T_{\frac{n}{2}+1}; \quad n \text{ odd: } T_{\frac{n+1}{2}},\ T_{\frac{n+3}{2}}`], n: 'The middle term sits where the binomial coefficients are largest. If n is even, there is one middle term, the term number n over two plus one. If n is odd, there are two middle terms, one on each side of the centre. The plot shows the tenth power: the coefficients rise to two hundred fifty-two at r equal to five and then fall back in a mirror image.' }),
    sl('check', 'Quick check: one middle term or two?', { b: 'The expansion of a sum raised to the seventh power has exactly one middle term. True or false?', chk: 'tf5', n: 'Is the power odd or even?' }),
    sl('example', 'Worked example 3: two middle terms', { b: r`Find the middle terms of $(x + 2y)^{7}$.`, ul: [r`**Odd power —** two middle terms, $T_{4}$ and $T_{5}$`, r`**$T_{4}$ —** $\binom{7}{3}x^{4}(2y)^{3} = 280x^{4}y^{3}$`, r`**$T_{5}$ —** $\binom{7}{4}x^{3}(2y)^{4} = 560x^{3}y^{4}$`], v: tblWE3b, n: 'The power seven is odd, so there are two middle terms, the fourth and the fifth. The fourth term has r equal to three: thirty-five times x to the fourth times the cube of two y, which is two hundred eighty x to the fourth y cubed. The fifth term has r equal to four: thirty-five times x cubed times the fourth power of two y, which is five hundred sixty x cubed y to the fourth.' }),
    sl('check', 'Quick check: the greatest coefficient', { b: 'What is the greatest binomial coefficient in the expansion of one plus x, to the eighth power?', chk: 'm11', n: 'It belongs to the middle term.' }),
    sl('concept', 'Equal binomial coefficients', { b: r`Since $\binom{n}{r} = \binom{n}{n-r}$, if $\binom{n}{r} = \binom{n}{s}$ with $r \ne s$, then $r + s = n$. This finds an unknown power when two coefficients are equal.`, v: tblSym, n: 'Choosing r objects to take is the same as choosing n minus r to leave, so the binomial coefficients are symmetric. The table shows the twelfth power: sixty-six appears at both r equal to two and r equal to ten, two hundred twenty at three and nine, and so on. If two binomial coefficients with different lower numbers are equal, those lower numbers add up to n. We use this in the next example.' }),
    sl('example', 'Worked example 4: equal coefficients', { b: r`In the expansion of $(1 + x)^{n}$ the coefficients of $x^{7}$ and $x^{13}$ are equal. Find $n$.`, ul: [r`**Coefficients —** $\binom{n}{7} = \binom{n}{13}$`, r`**Equal, with different lower numbers —** $7 + 13 = n$`, r`**So $n = 20$**`], v: tblWE4, n: 'The coefficient of x to the seventh is n choose seven, and the coefficient of x to the thirteenth is n choose thirteen. The two are equal, and seven and thirteen are different. So they must add up to n, which gives n equal to twenty. As a check, twenty choose seven and twenty choose thirteen are both seventy-seven thousand five hundred twenty.' }),
    sl('check', 'Quick check: equal combinations', { b: 'If fifteen choose four equals fifteen choose r, and r is not four, what is r?', chk: 'fb5', n: 'The two lower numbers add up to fifteen.' }),
    sl('summary', 'Summary', { ul: [r`$T_{r+1} = \binom{n}{r}a^{n-r}b^{r}$; the term number is $r + 1$`, r`A particular term: solve for $r$, which must be a whole number from $0$ to $n$`, r`Middle term: even $n$ gives $T_{n/2+1}$; odd $n$ gives two terms`, r`$\binom{n}{r} = \binom{n}{s}$ with $r \ne s$ means $r + s = n$`], v: summary2, n: 'To sum up. The general term gives any single term. To find a term with a given power of x, collect the power of x in terms of r and solve, checking that r is a whole number in range. An even power has one middle term and an odd power has two. Equal binomial coefficients with different lower numbers have lower numbers that add up to n.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**General or particular term (2–3 marks):** the formula, the value of $r$, the simplified term', '**Term independent of $x$ (3–5 marks):** the power in terms of $r$, solve, then the value', '**Middle terms (2–3 marks):** decide even or odd first', '**Mistake:** taking the $r$th term with index $r$ instead of $r - 1$', '**Mistake:** forgetting the number or sign inside the bracket when raising it to the power', '**Mistake:** accepting a fractional $r$'], n: 'In questions about a particular term, marks go for the general term, for the value of r, and for the simplified term. For the term free of x, show the power of x in terms of r, solve, and give the value. For middle terms, first decide whether the power is even or odd. Avoid these slips: using the term number as r, forgetting the sign or number inside a bracket, and accepting an r that is not a whole number.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'cbse-11-mathematics-ch07', version: 1, title: 'Binomial Theorem — chapter notes', language: 'en',
  sections: [
    { heading: '1. Pascal\'s triangle', body_md: r`Write $1$ at the top. Every row begins and ends with $1$ and each inner entry is **the sum of the two entries above it**. Row $n$ (the top row is row $0$) lists the numbers $\binom{n}{0}, \binom{n}{1}, \ldots, \binom{n}{n}$, which are the coefficients of $(a + b)^{n}$.\n\nThe rows are symmetric, and row $n$ adds up to $2^{n}$. Row $7$ is $1, 7, 21, 35, 35, 21, 7, 1$.\n\nThe triangle was known long before Pascal: Pingala in India (about the second century before the common era), Persian and Chinese mathematicians (Yang Hui, about the thirteenth century) and later Pascal (about the 1650s). Pascal's triangle is the usual name in Europe.`, key_terms: [{ term: "Pascal's triangle", definition_md: 'A triangle of numbers in which each inner entry is the sum of the two above it; row $n$ gives the coefficients of $(a+b)^{n}$.' }, { term: 'Binomial coefficient', definition_md: r`$\binom{n}{r} = {}^{n}C_{r} = \dfrac{n!}{r!\,(n-r)!}$, the number of ways to choose $r$ of $n$ objects.` }], formulas: [{ latex: r`\binom{n}{r} + \binom{n}{r-1} = \binom{n+1}{r}`, label: "Pascal's rule" }, { latex: r`\binom{n}{r} = \binom{n}{n-r}`, label: 'Symmetry' }], visual: figPascal, visuals: [tblExp, tblHist], topic_ids: [topic(1)] },
    { heading: '2. The binomial theorem and its proof', body_md: r`For every positive integer $n$,\n\n$$(a + b)^{n} = \binom{n}{0}a^{n} + \binom{n}{1}a^{n-1}b + \binom{n}{2}a^{n-2}b^{2} + \cdots + \binom{n}{n}b^{n} = \sum_{r=0}^{n}\binom{n}{r}a^{n-r}b^{r}$$\n\n**Proof by counting.** The product of the $n$ brackets $(a + b)(a + b)\cdots(a + b)$ is formed by choosing $a$ or $b$ from every bracket and multiplying. If $b$ is chosen from exactly $r$ brackets, the term is $a^{n-r}b^{r}$, and there are $\binom{n}{r}$ ways to pick those brackets. Adding over $r = 0, 1, \ldots, n$ gives the theorem.\n\nThere is a second proof of the theorem by mathematical induction; induction is formative only in this course, so the counting proof above is the one to learn.`, key_terms: [{ term: 'Binomial theorem', definition_md: r`The expansion of $(a+b)^{n}$ as $\sum_{r=0}^{n}\binom{n}{r}a^{n-r}b^{r}$ for a positive integer $n$.` }], formulas: [{ latex: r`(a+b)^{n} = \sum_{r=0}^{n}\binom{n}{r}a^{n-r}b^{r}`, label: 'Binomial theorem' }], visual: tblChoose, visuals: [tblThm], topic_ids: [topic(1)] },
    { heading: '3. Features and special cases', body_md: r`- The expansion has **$n + 1$ terms**, and the powers of $a$ and $b$ add up to $n$ in every term.\n- Terms equally far from the two ends have equal coefficients.\n- Putting $a = b = 1$: $\binom{n}{0} + \binom{n}{1} + \cdots + \binom{n}{n} = 2^{n}$.\n- Putting $a = 1$, $b = -1$: $\binom{n}{0} - \binom{n}{1} + \binom{n}{2} - \cdots = 0$, so the coefficients in the even places and in the odd places have the same sum, $2^{n-1}$.\n- $(a - b)^{n}$: use $-b$ as the second term, so the signs alternate.\n- $(a + b)^{n} + (a - b)^{n}$ keeps only the even powers of $b$ and doubles them; $(a + b)^{n} - (a - b)^{n}$ keeps only the odd powers and doubles them.\n- When a term is a fraction, write $\dfrac{1}{x}$ as $x^{-1}$ and combine the powers.`, key_terms: [{ term: 'Alternating signs', definition_md: 'Signs that go $+, -, +, -, \\ldots$, which happens when the second term is negative.' }], formulas: [{ latex: r`\sum_{r=0}^{n}\binom{n}{r} = 2^{n}`, label: 'Sum of the coefficients' }, { latex: r`\sum_{r=0}^{n}(-1)^{r}\binom{n}{r} = 0`, label: 'Alternating sum' }], visual: tblFeat, visuals: [tblWE1, tblFrac], topic_ids: [topic(1)] },
    { heading: '4. Numerical applications', body_md: r`**Values.** Split a number into a round number and a small one, for example $52^{4} = (50 + 2)^{4}$, and add the terms.\n\n**Estimates.** For a small $x$, $(1 + x)^{n} = 1 + nx + \binom{n}{2}x^{2} + \cdots$; the terms shrink fast, so a few terms give a good estimate. Check how many decimal places you need before you stop.\n\n**Remainders and divisibility.** Write the number as a multiple of the divisor plus or minus a small number, $(km \pm 1)^{e}$. Every term except the last has the factor $m$, so only the last term matters: $(-1)^{e}$ or $1$. A remainder must be between $0$ and $m - 1$, so $-1$ is written as $m - 1$.`, key_terms: [{ term: 'Remainder', definition_md: 'What is left when a number is divided by another; it lies between $0$ and the divisor minus $1$.' }], formulas: [{ latex: r`(1 + x)^{n} \approx 1 + nx + \binom{n}{2}x^{2}`, label: 'Three-term estimate for small $x$' }], visual: tblWE2, visuals: [tblApprox, tblRem, tblWE3], topic_ids: [topic(1)] },
    { heading: '5. The general term (formative)', body_md: r`In $(a + b)^{n}$ the **$(r+1)$th term** is\n\n$$T_{r+1} = \binom{n}{r}a^{n-r}b^{r}, \quad r = 0, 1, \ldots, n.$$\n\nFor the $k$th term put $r = k - 1$. The $(n + 1)$th term from the beginning is the first term from the end, and the $k$th term from the end is the $(n - k + 2)$th term from the beginning. Keep the sign and the coefficient of each term inside the bracket when raising it to the power.\n\nThis topic is for formative assessment only; it is taught here but kept light.`, key_terms: [{ term: 'General term', definition_md: r`$T_{r+1} = \binom{n}{r}a^{n-r}b^{r}$, the term with $b^{r}$.` }], formulas: [{ latex: r`T_{r+1} = \binom{n}{r}a^{n-r}b^{r}`, label: 'General term' }], visual: tblGen, visuals: [tblT6, tblWE1b], topic_ids: [topic(2)] },
    { heading: '6. A particular term and the term independent of x (formative)', body_md: r`To find the term containing $x^{k}$:\n\n1. Write $T_{r+1}$ and collect the power of $x$ as an expression in $r$.\n2. Set it equal to $k$ and solve for $r$.\n3. If $r$ is a whole number with $0 \le r \le n$, substitute it; otherwise **there is no such term**.\n\nFor the **term independent of $x$** take $k = 0$. Example: in $\left(x^{3} + \dfrac{2}{x^{2}}\right)^{10}$ the power of $x$ is $30 - 5r$, zero at $r = 6$, and the term is $\binom{10}{6}2^{6} = 13440$.`, key_terms: [{ term: 'Term independent of $x$', definition_md: 'The term in which the power of $x$ is $0$ (the constant term).' }], formulas: [{ latex: r`\text{power of } x \text{ in } T_{r+1} = k`, label: 'Condition for $x^{k}$' }], visual: flowFind, visuals: [tblExp10, tblWE2b], topic_ids: [topic(2)] },
    { heading: '7. Middle terms and equal coefficients (formative)', body_md: r`- $n$ **even:** one middle term, $T_{\frac{n}{2}+1}$, with the greatest coefficient $\binom{n}{n/2}$.\n- $n$ **odd:** two middle terms, $T_{\frac{n+1}{2}}$ and $T_{\frac{n+3}{2}}$, whose binomial coefficients are equal.\n- $\binom{n}{r} = \binom{n}{s}$ with $r \ne s$ gives $r + s = n$.\n\nThe binomial coefficients rise to the middle and fall again, so the middle term has the greatest binomial coefficient (not always the greatest term, because the numbers inside the bracket also matter).`, key_terms: [{ term: 'Middle term', definition_md: 'The term at the centre of the expansion: one term for an even power, two for an odd power.' }], formulas: [{ latex: r`\binom{n}{r} = \binom{n}{s},\ r \ne s \ \Rightarrow\ r + s = n`, label: 'Equal coefficients' }], visual: plotMid, visuals: [tblWE3b, tblWE4], topic_ids: [topic(2)] },
  ],
  exam_tips_md: r`**How marks are awarded**\n- *Expansion of a sum or difference (2–5 marks):* the row or $\binom{n}{r}$ for the coefficients, the substitution of both terms (sign and number inside the bracket), the simplified terms.\n- *Numerical value or estimate (2–3 marks):* the split of the number, the terms listed, the total; the stated number of decimal places.\n- *Remainder or divisibility (3–5 marks):* the nearby multiple, the term without the factor, the remainder written between $0$ and the divisor.\n- *Proof of the theorem or of a sum of coefficients (3–5 marks):* the choice of one letter from each bracket, $\binom{n}{r}$ ways, the sum over $r$; or the substitutions $a = b = 1$ and $a = 1, b = -1$.\n- *General, particular and middle terms (2–5 marks, formative):* the general term, the value of $r$, the simplified term; even or odd first for middle terms.\n\n**Common mistakes**\n1. Losing the sign of a negative second term.\n2. Not raising the number in front of a letter to the power, as in $(3x)^{4}$.\n3. Writing $(a+b)^{n} = a^{n} + b^{n}$.\n4. Using the term number as $r$ (the $k$th term has $r = k - 1$).\n5. Accepting a fractional $r$ for a term containing a given power of $x$.\n6. Forgetting that $n$ even has one middle term and $n$ odd has two.\n7. Leaving a remainder as $-1$ instead of the divisor minus $1$.`,
  status: 'draft', provenance: d1.provenance,
};

const fcard = (id, front_md, back_md, tag, t) => ({ id, front_md, back_md, tag, topic_id: topic(t) });
